begin;
create function pg_temp.assert(ok boolean,message text) returns void language plpgsql as $$ begin if not coalesce(ok,false) then raise exception 'POS control check failed: %',message;end if;end $$;
insert into public.onebite_users(id,name,username,role,active) values ('11111111-1111-4111-8111-111111111111','POS control test Owner','pos-control-test-owner','Owner',true),('22222222-2222-4222-8222-222222222222','POS control test Cashier','pos-control-test-cashier','Cashier',true);
insert into public.onebite_credentials(user_id,pin_hash,must_change) values ('11111111-1111-4111-8111-111111111111','test-only',false),('22222222-2222-4222-8222-222222222222','test-only',false);
insert into public.onebite_sessions(token_hash,user_id,expires_at,mfa_at) values(repeat('1',64),'11111111-1111-4111-8111-111111111111',now()+interval '1 day',now()),(repeat('2',64),'22222222-2222-4222-8222-222222222222',now()+interval '1 day',null);
insert into public.onebite_role_permissions(role,permission) values('Cashier','pos.access'),('Cashier','shifts.manage'),('Owner','cash.withdraw') on conflict do nothing;
insert into public.onebite_sites(id,name,active) values(999998,'POS control Assigned',true),(999999,'POS control Other',true);
insert into public.onebite_user_sites(user_id,site_id) values('22222222-2222-4222-8222-222222222222',999998);
create function pg_temp.payload(r integer,gen integer default 0) returns jsonb language sql as $$ select jsonb_build_object('siteId',999998,'deviceId','33333333-3333-4333-8333-333333333333','proofHash',repeat('a',64),'requestId',lpad(r::text,8,'0')||'-4444-4444-8444-444444444444','generation',gen); $$;
select pg_temp.assert(not has_function_privilege('anon','public.onebite_pos_control(text,jsonb,text)','execute'),'anonymous clients cannot run control API');
select pg_temp.assert(not has_function_privilege('authenticated','public.onebite_pos_control(text,jsonb,text)','execute'),'JWT clients cannot bypass custom session checks');
select pg_temp.assert(not has_table_privilege('service_role','public.onebite_pos_control_events','update'),'events cannot be rewritten');
select pg_temp.assert(not has_table_privilege('anon','public.onebite_pos_devices','select'),'device proofs stay private');
set local role service_role;
do $$ declare r jsonb; p jsonb; begin
 perform pg_temp.assert(public.onebite_pos_control('workspace',pg_temp.payload(1),repeat('f',64))->>'error'='unauthorized','unknown sessions denied');
 perform pg_temp.assert(public.onebite_pos_control('workspace',pg_temp.payload(1)||'{"siteId":999999}',repeat('2',64))->>'error'='forbidden','assigned sites enforced');
 r=public.onebite_pos_control('device.claim',pg_temp.payload(1),repeat('2',64));perform pg_temp.assert(not r ? 'error','Cashier can register assigned device');
 perform pg_temp.assert(public.onebite_pos_control('device.claim',pg_temp.payload(1),repeat('2',64))=r,'claim retry returns original result despite changed generation');
 perform pg_temp.assert(public.onebite_pos_control('device.claim',pg_temp.payload(1)||'{"generation":1}',repeat('2',64))->>'error'='request_conflict','altered idempotency payload denied');
 r=public.onebite_pos_control('workspace',pg_temp.payload(1),repeat('2',64));perform pg_temp.assert(r->>'ordering'='true' and r->>'generation'='1','matching credential receives ordering authority');
 perform pg_temp.assert(not r ? 'proofHash' and not r ? 'deviceId','workspace leaks no device credential');
 r=public.onebite_pos_control('workspace',pg_temp.payload(1)||jsonb_build_object('proofHash',repeat('b',64)),repeat('2',64));perform pg_temp.assert(r->>'ordering'='false','same device UUID without secret cannot receive orders');
 perform pg_temp.assert(public.onebite_pos_control('device.claim',pg_temp.payload(2,1)||'{"deviceId":"55555555-5555-4555-8555-555555555555"}',repeat('1',64))->>'error'='device_in_use','another device cannot take registered site');
 perform pg_temp.assert(public.onebite_pos_control('shift.open',pg_temp.payload(3,1)||jsonb_build_object('cash','10000','source','supply','proofHash',repeat('b',64)),repeat('1',64))->>'error'='device_required','device proof required for opening');
 perform pg_temp.assert(public.onebite_pos_control('shift.open',pg_temp.payload(3,1)||'{"cash":"10000","source":"supply"}',repeat('2',64))->>'error'='cash_supplier_required','Cashier cannot fabricate supplied opening cash');
 p=pg_temp.payload(3,1)||'{"cash":"10000","source":"supply"}';r=public.onebite_pos_control('shift.open',p,repeat('1',64));perform pg_temp.assert(not r ? 'error','Owner supplies opening cash');
 perform pg_temp.assert(public.onebite_pos_control('shift.open',p,repeat('1',64))=r,'opening retry has exactly one shift');
 perform pg_temp.assert((select count(*) from public.onebite_pos_shifts where site_id=999998)=1,'retry does not duplicate cash opening');
 perform pg_temp.assert(public.onebite_pos_control('shift.open',pg_temp.payload(4,1)||'{"cash":"0","source":"zero"}',repeat('2',64))->>'error'='shift_active','one shared active shift');
 perform pg_temp.assert(public.onebite_pos_control('device.release',pg_temp.payload(4,1),repeat('1',64))->>'error'='shift_active','release blocked during active shift');
 p=pg_temp.payload(5,1)||jsonb_build_object('cash','9000','shiftId','00000003-4444-4444-8444-444444444444');
 perform pg_temp.assert(public.onebite_pos_control('shift.close',p,repeat('2',64))->>'error'='custodian_required','other staff cannot impersonate cash holder');
 r=public.onebite_pos_control('shift.close',p,repeat('1',64));perform pg_temp.assert(not r ? 'error','cash holder can close and retain actual cash');
 perform pg_temp.assert(public.onebite_pos_control('shift.close',p,repeat('1',64))=r,'closing retry has exactly one result');
 perform pg_temp.assert((select difference from public.onebite_pos_shifts where site_id=999998)=-1000,'cash shortage remains recorded');
 perform pg_temp.assert((select cash from public.onebite_pos_custody where site_id=999998)=9000,'cash custody survives closing');
 perform pg_temp.assert(public.onebite_pos_control('shift.open',pg_temp.payload(6,1)||'{"cash":"0","source":"zero"}',repeat('2',64))->>'error'='handover_required','other staff cannot bypass retained custody with zero opening');
 perform pg_temp.assert(public.onebite_pos_control('shift.open',pg_temp.payload(6,1)||'{"cash":"10000","source":"supply"}',repeat('1',64))->>'error'='retained_cash_required','retained cash cannot be double-counted as supply');
 p=pg_temp.payload(6,1)||'{"cash":"9000","source":"retained"}';perform pg_temp.assert(not public.onebite_pos_control('shift.open',p,repeat('1',64)) ? 'error','same holder reuses exact retained cash');
 perform pg_temp.assert((select cash from public.onebite_pos_custody where site_id=999998)=9000,'carry-forward does not add cash twice');
 p=pg_temp.payload(7,1)||jsonb_build_object('cash','0','shiftId','00000006-4444-4444-8444-444444444444');perform pg_temp.assert(not public.onebite_pos_control('shift.close',p,repeat('1',64)) ? 'error','close zero counted cash');
 perform pg_temp.assert(not public.onebite_pos_control('device.release',pg_temp.payload(8,1),repeat('1',64)) ? 'error','closed device can be released');
 perform pg_temp.assert(public.onebite_pos_control('device.claim',pg_temp.payload(9,1),repeat('1',64))->>'error'='device_changed','stale generation cannot reactivate');
 p=pg_temp.payload(9,2)||'{"deviceId":"55555555-5555-4555-8555-555555555555"}';perform pg_temp.assert(not public.onebite_pos_control('device.claim',p,repeat('1',64)) ? 'error','new device can register after release');
 perform pg_temp.assert(public.onebite_pos_control('shift.open',pg_temp.payload(10,3)||'{"cash":"0","source":"zero"}',repeat('2',64))->>'error'='device_required','released device cannot open shifts');
end $$;
reset role;
delete from public.onebite_role_permissions where role='Cashier' and permission='shifts.manage';
set local role service_role;
select pg_temp.assert(public.onebite_pos_control('device.claim',pg_temp.payload(99,3),repeat('2',64))->>'error'='forbidden','revocation applies before idempotency or mutation');
reset role;
rollback;
